package com.guocheng.mediapocket;
import android.app.*;import android.content.*;
public final class FullscreenMode {
 static void apply(Activity a,String mode,boolean reset)throws Exception{SharedPreferences p=a.getSharedPreferences("data",0);float zoom=reset?1f:FullscreenRules.zoom(mode,p.getFloat("gestureZoom",1f));p.edit().putString("aspectMode",mode).putFloat("gestureZoom",zoom).putBoolean("fullscreenNoCrop.v1",true).apply();SourceSubtitleLoader.set(a,"zoom",zoom);Object video=OnlineSubtitleSearch.field(a,"video");if(video!=null)OnlineSubtitleSearch.call(video,"aspect",new Class<?>[]{String.class},mode);OnlineSubtitleSearch.call(a,"applyZoom",new Class<?>[0]);}
 public static void initialize(Object session){try{Object owner=OnlineSubtitleSearch.field(session,"a");if(!(owner instanceof Activity))return;Activity a=(Activity)owner;SharedPreferences p=a.getSharedPreferences("data",0);boolean migrated=p.getBoolean("fullscreenNoCrop.v1",false);String mode=FullscreenRules.mode(p.getString("aspectMode","fit"),migrated);if(!migrated||mode.equals("stretch"))apply(a,mode,true);}catch(Exception ignored){}}
 public static void sync(Activity a){try{if(a.getSharedPreferences("data",0).getString("aspectMode","stretch").equals("stretch"))apply(a,"stretch",true);}catch(Exception ignored){}}
 public static void choose(Object owner){if(!(owner instanceof Activity))return;Activity a=(Activity)owner;String[] labels={"铺满且不裁切 · 拉伸画面","原始比例 · 完整画面，可能有黑边","铺满屏幕 · 裁切边缘","16:9","4:3"};String[] modes={"stretch","fit","crop","16:9","4:3"};String mode=a.getSharedPreferences("data",0).getString("aspectMode","stretch");int index=0;for(int i=0;i<modes.length;i++)if(modes[i].equals(mode))index=i;new AlertDialog.Builder(a).setTitle("画面比例 · 选择后恢复100%缩放").setSingleChoiceItems(labels,index,(d,n)->{try{apply(a,modes[n],true);d.dismiss();OnlineSubtitleSearch.call(a,"controls",new Class<?>[]{boolean.class},true);OnlineSubtitleSearch.call(a,"showHud",new Class<?>[]{String.class},labels[n]);}catch(Exception e){OnlineSubtitleSearch.message(a,"比例设置失败："+e.getClass().getSimpleName());}}).setNegativeButton("关闭",null).show();}
}
